export const FRIENDS_QUESTION_REGISTRY: Record<QuizDifficulty, { foundation: QuizQuestion[]; growth: QuizQuestion[]; mastery: QuizQuestion[]; }> = {
  easy: {
    foundation: FRIENDS_EASY_FOUNDATION,
    growth: FRIENDS_EASY_GROWTH,
    mastery: FRIENDS_EASY_MASTERY
  },
  medium: {
    foundation: FRIENDS_MEDIUM_FOUNDATION,
    growth: FRIENDS_MEDIUM_GROWTH,
    mastery: FRIENDS_MEDIUM_MASTERY
  },
  hard: {
    foundation: FRIENDS_HARD_FOUNDATION,
    growth: FRIENDS_HARD_GROWTH,
    mastery: FRIENDS_HARD_MASTERY
  },
};

export function getFriendsStageQuestions(difficulty: QuizDifficulty, stage: 1 | 2 | 3): QuizQuestion[] {
  const diffKey = (difficulty || 'easy').toLowerCase() as QuizDifficulty;
  const stageMap = FRIENDS_QUESTION_REGISTRY[diffKey] || FRIENDS_QUESTION_REGISTRY.easy;
  if (stage === 1) return stageMap.foundation;
  if (stage === 2) return stageMap.growth;
  return stageMap.mastery;
}

export function getFriendsLevelQuestions(difficulty: QuizDifficulty, level: number): QuizQuestion[] {
  const stage = level <= 10 ? 1 : level <= 20 ? 2 : 3;
  const stagePool = getFriendsStageQuestions(difficulty, stage);
  const offset = (level - 1) % 10;
  const startIndex = offset * 5;
  return stagePool.slice(startIndex, startIndex + 5);
}
